using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ShrinkAction", menuName = "Data/Battle/Battle Actions/Orion/Shrink Action")]
public class ShrinkAction : BattleAction
{
	public override void AreaCastTargetAmount(List<GameObject> targets, int amount, GameObject source)
	{
		for (int i = 0; i < targets.Count; i++)
		{
			targets[i].GetComponent<CorruptedAnimalCorruptionStats>().ModifyMaxOverCorruption(-amount);
		}
		if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.PlayerTurn)
		{
			ReferenceSingleton<GameStateManager>.Instance.SetChooseActionState();
		}
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		target.GetComponent<CorruptedAnimalCorruptionStats>().ModifyMaxOverCorruption(-amount);
		if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.PlayerTurn)
		{
			ReferenceSingleton<GameStateManager>.Instance.SetChooseActionState();
		}
	}
}
